#!/usr/bin/env bash
# Generated by plan_move.sh - close VS Code, Jupyter, Vivado, STM32CubeIDE, conda terminals first.
set -u
DEST=/mnt/data/pan/home
sudo mkdir -p "$DEST" && sudo chown "$USER:$USER" /mnt/data/pan "$DEST"
mv1() { p=$1; n=$(basename "$p"); [[ -L $p ]] && { echo "skip $p (already a link)"; return; }
  [[ -e $DEST/$n ]] && { echo "skip $p ($DEST/$n exists)"; return; }
  echo ">> $p"; if rsync -aHAX --info=progress2 "$p/" "$DEST/$n/"; then rm -rf "$p" && ln -s "$DEST/$n" "$p" && echo "   ok"; else echo "   copy FAILED, original kept"; rm -rf "${DEST:?}/$n"; fi; }
mv1 /home/panmanzee/anaconda3
mv1 /home/panmanzee/.cache
mv1 /home/panmanzee/STM32Cube
mv1 /home/panmanzee/Downloads
mv1 /home/panmanzee/STM32CubeMX
mv1 /home/panmanzee/.vscode
mv1 /home/panmanzee/.hermes
mv1 /home/panmanzee/.npm
df -h /
